public class OwnedPicklistOrderObserver {
 public static String observe(String row) {
  Savepoint point=Database.setSavepoint(); Map<String,Object> result=new Map<String,Object>();
  try {
   Account parent=new Account(Name='Owned sort parent'); Database.insert(parent,AccessLevel.SYSTEM_MODE);
   List<OwnedSortEntry__c> entries=new List<OwnedSortEntry__c>{
    new OwnedSortEntry__c(Name='a',Stage__c='Alpha',Text__c='Alpha',Parent__c=parent.Id),
    new OwnedSortEntry__c(Name='z1',Stage__c='Zulu',Text__c='Zulu',Parent__c=parent.Id),
    new OwnedSortEntry__c(Name='m',Stage__c='Middle',Text__c='Middle',Parent__c=parent.Id),
    new OwnedSortEntry__c(Name='z2',Stage__c='Zulu',Text__c='Zulu',Parent__c=parent.Id),
    new OwnedSortEntry__c(Name='n',Parent__c=parent.Id)};
   if(row.startsWith('U')||row=='M01') entries.add(new OwnedSortEntry__c(Name='u',Stage__c='Beta',Text__c='Beta',Parent__c=parent.Id));
   Database.insert(entries,AccessLevel.SYSTEM_MODE);
   if(row=='M01') {
    List<String> values=new List<String>(); for(Schema.PicklistEntry option:OwnedSortEntry__c.Stage__c.getDescribe().getPicklistValues())values.add(option.getValue());
    result.put('values',values);result.put('restricted',OwnedSortEntry__c.Stage__c.getDescribe().isRestrictedPicklist());
    OwnedSortEntry__c stored=[SELECT Stage__c FROM OwnedSortEntry__c WHERE Name='u' WITH SYSTEM_MODE LIMIT 1];result.put('unknown',stored.Stage__c);
   } else {
    String kind=row.substring(1);String order;Boolean child=false;Id parentId=parent.Id;
    if (kind=='01') { order='Stage__c ASC, Name ASC'; child=false; }
    if (kind=='02') { order='Stage__c DESC, Name ASC'; child=false; }
    if (kind=='03') { order='Stage__c ASC NULLS FIRST, Name ASC'; child=false; }
    if (kind=='04') { order='Stage__c ASC NULLS LAST, Name ASC'; child=false; }
    if (kind=='05') { order='Stage__c DESC NULLS FIRST, Name ASC'; child=false; }
    if (kind=='06') { order='Stage__c DESC NULLS LAST, Name ASC'; child=false; }
    if (kind=='07') { order='Stage__c ASC NULLS LAST, Name ASC LIMIT 1'; child=false; }
    if (kind=='08') { order='Stage__c DESC NULLS LAST, Name ASC LIMIT 1'; child=false; }
    if (kind=='09') { order='Stage__c ASC NULLS LAST, Name ASC'; child=true; }
    if (kind=='10') { order='Stage__c DESC NULLS FIRST, Name ASC'; child=true; }
    if (kind=='11') { order='Text__c ASC NULLS LAST, Name ASC'; child=false; }
    if (kind=='12') { order='Text__c DESC NULLS FIRST, Name ASC'; child=false; }
    List<SObject> rows;
    if(child) {Account stored=Database.query('SELECT Id,(SELECT Name FROM OwnedEntries__r ORDER BY '+order+') FROM Account WHERE Id = :parentId WITH SYSTEM_MODE');rows=stored.getSObjects('OwnedEntries__r');}
    else rows=Database.query('SELECT Name FROM OwnedSortEntry__c WITH SYSTEM_MODE ORDER BY '+order);
    List<String> names=new List<String>();for(SObject entry:rows)names.add((String)entry.get('Name'));result.put('order',names);
   }
  } catch(Exception issue){result.put('exceptionType',issue.getTypeName());result.put('message',issue.getMessage());}
  finally{Database.rollback(point);}return JSON.serialize(result);
 }
}

